create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','member','client');
create type public.lead_stage as enum ('new','qualified','proposal','negotiation','won','lost');
create type public.task_status as enum ('open','completed','cancelled');
create type public.project_status as enum ('planning','active','on_hold','completed');
create type public.document_status as enum ('draft','sent','viewed','accepted','paid','overdue','void');

create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.memberships (organization_id uuid references public.organizations on delete cascade, user_id uuid references public.profiles on delete cascade, role public.app_role not null default 'member', primary key(organization_id,user_id));
create table public.customers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, owner_id uuid references public.profiles, auth_user_id uuid references public.profiles, name text not null, company text, email text, phone text, status text not null default 'active', lifetime_value numeric(12,2) not null default 0, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, owner_id uuid references public.profiles, name text not null, company text, email text, source text, stage public.lead_stage not null default 'new', estimated_value numeric(12,2) not null default 0, last_contact_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, assignee_id uuid references public.profiles, customer_id uuid references public.customers on delete cascade, lead_id uuid references public.leads on delete cascade, title text not null, description text, priority smallint not null default 2 check(priority between 1 and 3), status public.task_status not null default 'open', due_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, customer_id uuid references public.customers on delete set null, owner_id uuid references public.profiles, name text not null, description text, status public.project_status not null default 'planning', budget numeric(12,2), progress smallint not null default 0 check(progress between 0 and 100), starts_on date, due_on date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.proposals (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, customer_id uuid references public.customers, lead_id uuid references public.leads, number text not null, title text not null, amount numeric(12,2) not null default 0, status public.document_status not null default 'draft', content jsonb not null default '{}', valid_until date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,number));
create table public.invoices (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, customer_id uuid not null references public.customers, project_id uuid references public.projects, number text not null, amount numeric(12,2) not null default 0, status public.document_status not null default 'draft', issued_on date, due_on date, paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,number));
create table public.files (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, customer_id uuid references public.customers, project_id uuid references public.projects, uploader_id uuid references public.profiles, bucket text not null default 'crm-files', path text not null, name text not null, mime_type text, size_bytes bigint, created_at timestamptz not null default now(), unique(bucket,path));
create table public.activities (id bigint generated always as identity primary key, organization_id uuid not null references public.organizations on delete cascade, actor_id uuid references public.profiles, entity_type text not null, entity_id uuid, action text not null, payload jsonb not null default '{}', created_at timestamptz not null default now());
create table public.automations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, trigger_type text not null, config jsonb not null default '{}', enabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create index leads_org_stage_idx on public.leads(organization_id,stage); create index customers_org_idx on public.customers(organization_id); create index tasks_org_due_idx on public.tasks(organization_id,due_at) where status='open'; create index projects_org_status_idx on public.projects(organization_id,status); create index activities_org_created_idx on public.activities(organization_id,created_at desc); create index files_customer_idx on public.files(customer_id);
create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at();
create trigger customers_updated before update on public.customers for each row execute function public.set_updated_at(); create trigger leads_updated before update on public.leads for each row execute function public.set_updated_at(); create trigger projects_updated before update on public.projects for each row execute function public.set_updated_at(); create trigger proposals_updated before update on public.proposals for each row execute function public.set_updated_at(); create trigger invoices_updated before update on public.invoices for each row execute function public.set_updated_at(); create trigger automations_updated before update on public.automations for each row execute function public.set_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,avatar_url) values(new.id,new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'avatar_url'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships where organization_id=org and user_id=auth.uid()) $$;
create function public.is_org_admin(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships where organization_id=org and user_id=auth.uid() and role='admin') $$;

alter table public.organizations enable row level security; alter table public.profiles enable row level security; alter table public.memberships enable row level security; alter table public.customers enable row level security; alter table public.leads enable row level security; alter table public.tasks enable row level security; alter table public.projects enable row level security; alter table public.proposals enable row level security; alter table public.invoices enable row level security; alter table public.files enable row level security; alter table public.activities enable row level security; alter table public.automations enable row level security;
create policy "members view organizations" on public.organizations for select using(public.is_org_member(id)); create policy "admins update organizations" on public.organizations for update using(public.is_org_admin(id));
create policy "users view own profile or colleagues" on public.profiles for select using(id=auth.uid() or exists(select 1 from public.memberships mine join public.memberships theirs using(organization_id) where mine.user_id=auth.uid() and theirs.user_id=profiles.id)); create policy "users update own profile" on public.profiles for update using(id=auth.uid());
create policy "members view memberships" on public.memberships for select using(public.is_org_member(organization_id)); create policy "admins manage memberships" on public.memberships for all using(public.is_org_admin(organization_id)) with check(public.is_org_admin(organization_id));
create policy "members manage customers" on public.customers for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id)); create policy "clients view own customer" on public.customers for select using(auth_user_id=auth.uid());
create policy "members manage leads" on public.leads for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy "members manage tasks" on public.tasks for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy "members manage projects" on public.projects for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id)); create policy "clients view projects" on public.projects for select using(exists(select 1 from public.customers c where c.id=customer_id and c.auth_user_id=auth.uid()));
create policy "members manage proposals" on public.proposals for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id)); create policy "clients view proposals" on public.proposals for select using(exists(select 1 from public.customers c where c.id=customer_id and c.auth_user_id=auth.uid()));
create policy "members manage invoices" on public.invoices for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id)); create policy "clients view invoices" on public.invoices for select using(exists(select 1 from public.customers c where c.id=customer_id and c.auth_user_id=auth.uid()));
create policy "members manage files" on public.files for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id)); create policy "clients view files" on public.files for select using(exists(select 1 from public.customers c where c.id=customer_id and c.auth_user_id=auth.uid()));
create policy "members view activities" on public.activities for select using(public.is_org_member(organization_id)); create policy "members add activities" on public.activities for insert with check(public.is_org_member(organization_id));
create policy "members view automations" on public.automations for select using(public.is_org_member(organization_id)); create policy "admins manage automations" on public.automations for all using(public.is_org_admin(organization_id)) with check(public.is_org_admin(organization_id));
